"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Activity, BarChart3, Check, FlaskConical, History, Play, RefreshCw, Square } from "lucide-react";
import { CartesianGrid, Legend, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

import { api, ApiClientError, OptimizationJob, OptimizationMetric, OptimizationPayload, OptimizationRow, OptimizationSelectionMode, RollingOptimizationWindow, StructureArtifact, StructureCandidate } from "@/lib/api";
import { DEFAULT_FORM } from "@/lib/default-form";
import { dateText, errorText, money, num, t } from "@/lib/i18n";
import type { BacktestResult, FormState, Parameters } from "@/lib/types";
import StructureChart from "@/components/StructureChart";

const metricOptions: Array<[OptimizationMetric,string]> = [
  ["sharpe_ratio","Sharpe"], ["total_return","Total return"], ["cagr","CAGR"],
  ["sortino_ratio","Sortino"], ["calmar_ratio","Calmar"], ["max_drawdown","Maximum drawdown"], ["net_pnl","Net PnL"],
];
const active = (job?: OptimizationJob|null) => Boolean(job && ["QUEUED","RUNNING"].includes(job.status));
const pct = (value: number|null|undefined) => value == null ? "—" : `${(value*100).toFixed(2)}%`;
const ratio = (value: number|null|undefined) => value == null ? "—" : value.toFixed(2);
const metricLabel = (metric: OptimizationMetric) => t(metricOptions.find(([key])=>key===metric)?.[1] ?? metric);
const metricValue = (row: OptimizationRow, metric: OptimizationMetric) => {
  const value = row[metric]; if (value == null) return "—";
  return ["total_return","cagr","max_drawdown"].includes(metric) ? pct(value) : metric === "net_pnl" ? money(value) : ratio(value);
};

export default function OptimizePage() {
  const [form,setForm]=useState<FormState>({...DEFAULT_FORM,parameters:{...DEFAULT_FORM.parameters}});
  const [mode,setMode]=useState<"single"|"rolling_6m">("single"),[selectionMode,setSelectionMode]=useState<OptimizationSelectionMode>("PERFORMANCE"),[fixedMA,setFixedMA]=useState(20);
  const [maMin,setMaMin]=useState(5),[maMax,setMaMax]=useState(200),[maStep,setMaStep]=useState(5);
  const [ranking,setRanking]=useState<OptimizationMetric>("sharpe_ratio");
  const [trainTest,setTrainTest]=useState({enabled:false,train_start:"2010-01-01",train_end:"2022-12-31",test_start:"2023-01-01",test_end:"2026-09-01"});
  const [jobs,setJobs]=useState<OptimizationJob[]>([]),[selected,setSelected]=useState<OptimizationJob|null>(null);
  const [error,setError]=useState(""),[starting,setStarting]=useState(false),[sortMetric,setSortMetric]=useState<OptimizationMetric>("sharpe_ratio");
  const [chartMetric,setChartMetric]=useState<OptimizationMetric>("sharpe_ratio"),[curves,setCurves]=useState<number[]>([]);
  const [curveData,setCurveData]=useState<Record<number,BacktestResult>>({});
  const combinations = maMax>=maMin && maStep>0 ? Math.floor((maMax-maMin)/maStep)+1 : 0;
  const validSearch = combinations>0 && combinations<=500 && maMin>=2 && maMax<=500 && (mode!=="rolling_6m"||(fixedMA>=2&&fixedMA<=500));

  useEffect(()=>{if(mode!=="rolling_6m")setSelectionMode("PERFORMANCE");},[mode]);

  const loadHistory=useCallback(async()=>{try{setJobs(await api.optimizations());}catch{setError(t("Optimization result unavailable"));}},[]);
  useEffect(()=>{loadHistory();},[loadHistory]);
  useEffect(()=>{
    if(!active(selected)) return;
    const timer=window.setInterval(async()=>{try{const fresh=await api.optimization(selected!.id);setSelected(fresh);if(!active(fresh))loadHistory();}catch{}},1500);
    return()=>window.clearInterval(timer);
  },[selected?.id,selected?.status,loadHistory]);
  useEffect(()=>{
    if(!curves.length){setCurveData({});return;}
    Promise.all(curves.map(async ma=>{
      const row=selected?.result.results?.find(item=>item.ma_period===ma); if(!row)return null;
      const record=await api.get(row.backtest_id); return record.result?[ma,record.result] as const:null;
    })).then(items=>setCurveData(Object.fromEntries(items.filter(Boolean) as Array<readonly [number,BacktestResult]>))).catch(()=>setError(t("Optimization result unavailable")));
  },[curves,selected?.id]);

  const rows=selected?.result.results??[];
  const sorted=useMemo(()=>[...rows].sort((a,b)=>(Number(b[sortMetric]??-Infinity)-Number(a[sortMetric]??-Infinity))),[rows,sortMetric]);
  const best=sorted[0];
  const nearby=best?[...rows].filter(row=>Math.abs(row.ma_period-best.ma_period)<=Math.max(1,Number(selected?.payload.ma_step??maStep))*5).sort((a,b)=>a.ma_period-b.ma_period):[];
  const stability=useMemo(()=>{
    if(!best||nearby.length<2)return false; const values=nearby.map(row=>Number(row[sortMetric])).filter(Number.isFinite);
    if(values.length<2)return false; return (Math.max(...values)-Math.min(...values))/Math.max(Math.abs(Number(best[sortMetric])),1e-9)<=.2;
  },[best,nearby,sortMetric]);
  const performanceData=useMemo(()=>[...rows].sort((a,b)=>a.ma_period-b.ma_period).map(row=>({ma:row.ma_period,value:["total_return","cagr","max_drawdown"].includes(chartMetric)?Number(row[chartMetric])*100:row[chartMetric]})),[rows,chartMetric]);
  const equityData=useMemo(()=>{
    const dates=new Set<string>(); Object.values(curveData).forEach(result=>result.equity_curve.forEach(row=>dates.add(row.timestamp.slice(0,10))));
    const maps=Object.fromEntries(Object.entries(curveData).map(([ma,result])=>[ma,new Map(result.equity_curve.map(row=>[row.timestamp.slice(0,10),row.strategy]))]));
    return [...dates].sort().map(date=>({date,...Object.fromEntries(Object.entries(maps).map(([ma,map])=>[`MA${ma}`,map.get(date)??null]))}));
  },[curveData]);

  const top=<K extends keyof FormState>(key:K,value:FormState[K])=>setForm({...form,[key]:value});
  const param=<K extends keyof Parameters>(key:K,value:Parameters[K])=>setForm({...form,parameters:{...form.parameters,[key]:value}});
  async function submit(event:React.FormEvent){
    event.preventDefault();if(!validSearch||starting)return;setStarting(true);setError("");
    const payload:OptimizationPayload={mode,selection_mode:mode==="rolling_6m"?selectionMode:"PERFORMANCE",backtest:form,ma_min:maMin,ma_max:maMax,ma_step:maStep,ranking_metric:ranking,train_test:trainTest,rolling:{fixed_ma_period:fixedMA,calendar_months:6,independent_test_segments:true}};
    try{const job=await api.createOptimization(payload);setSelected(job);setSortMetric(ranking);setChartMetric(ranking);setCurves([]);await loadHistory();}
    catch(reason){setError(reason instanceof ApiClientError?reason.details.message:t("Optimization could not start."));}
    finally{setStarting(false);}
  }
  const toggleCurve=(ma:number)=>setCurves(values=>values.includes(ma)?values.filter(item=>item!==ma):values.length<5?[...values,ma]:values);
  const progress=selected&&selected.progress_total?Math.min(100,selected.progress_current/selected.progress_total*100):0;

  return <main className="min-h-screen p-3 lg:p-4">
    <header className="mb-4 flex flex-wrap items-center justify-between gap-3 border-b border-[#223247] pb-3">
      <div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-md border border-emerald-400/30 bg-emerald-400/10 text-emerald-300"><FlaskConical size={19}/></div><div><h1 className="m-0 text-lg font-semibold">{t("Parameter optimization")}</h1><p className="m-0 text-[11px] text-slate-500">{t("MA period optimization")}</p></div></div>
      <nav className="flex gap-2"><Link className="rounded border border-[#304159] px-3 py-2 text-xs text-slate-300" href="/">{t("Back to backtest")}</Link><Link className="rounded border border-[#304159] px-3 py-2 text-xs text-slate-300" href="/data">{t("Data center")}</Link></nav>
    </header>
    {error&&<div role="alert" className="mb-4 rounded-lg border border-rose-400/30 bg-rose-400/10 p-3 text-sm text-rose-100">{error}</div>}
    <form onSubmit={submit} className="grid items-start gap-4 xl:grid-cols-[380px_minmax(0,1fr)]">
      <section className="panel grid gap-3 p-3 xl:sticky xl:top-3">
        <Section title="基本設定" open><div className="grid grid-cols-2 gap-2"><Field label="Ticker"><input className="input uppercase" value={form.ticker} onChange={e=>top("ticker",e.target.value.toUpperCase())}/></Field><Field label="Strategy"><select className="input" value={form.strategy} onChange={e=>top("strategy",e.target.value as FormState["strategy"])}><option value="simple">{t("Simple")}</option><option value="advanced">{t("Advanced")}</option><option value="advanced_day1_stop">{t("Advanced + Day1 Stop")}</option></select></Field><Field label="Start date"><input type="date" className="input" value={form.start_date} onChange={e=>top("start_date",e.target.value)}/></Field><Field label="End date"><input type="date" className="input" value={form.end_date} onChange={e=>top("end_date",e.target.value)}/></Field><Field label="Daily Intrabar Assumption"><select className="input" value={form.execution_policy} onChange={e=>top("execution_policy",e.target.value as FormState["execution_policy"])}><option value="conservative">{t("Conservative")}</option><option value="ohlc_heuristic">{t("OHLC Heuristic")}</option><option value="favorable">{t("Favorable")}</option></select></Field><Field label="Market data provider"><select className="input" value={form.market_data_provider} onChange={e=>top("market_data_provider",e.target.value as FormState["market_data_provider"])}><option value="auto">{t("Auto (cache → Yahoo → Stooq)")}</option><option value="yahoo">Yahoo</option><option value="alternative">Stooq</option></select></Field></div></Section>
        <Section title="Optimization method" open><Field label="Optimization method"><select className="input" value={mode} onChange={e=>setMode(e.target.value as "single"|"rolling_6m")}><option value="single">{t("Single Train / Test")}</option><option value="rolling_6m">{t("Re-optimize every 6 months")}</option></select></Field>{mode==="rolling_6m"&&<><Field label="均線選擇方式"><select className="input" value={selectionMode} onChange={e=>setSelectionMode(e.target.value as OptimizationSelectionMode)}><option value="PERFORMANCE">{t("依回測績效")}</option><option value="STRUCTURE_V1">{t("依 K 線結構")}</option></select></Field><div className="mt-2 rounded border border-cyan-400/20 bg-cyan-400/10 p-3 text-xs leading-5 text-cyan-100">{t("Use the prior 6 calendar months to select the best MA, then hold that MA fixed for the next 6 calendar months.")}</div></>}{mode!=="rolling_6m"&&<p className="m-0 text-[11px] text-slate-500">{t("Structure selection is available only for Rolling 6M.")}</p>}</Section>
        <Section title="Search settings" open><div className="grid grid-cols-3 gap-2"><NumberField label="Minimum period" value={maMin} onChange={setMaMin}/><NumberField label="Maximum period" value={maMax} onChange={setMaMax}/><NumberField label="Step" value={maStep} onChange={setMaStep}/></div><div className={`mt-2 rounded p-2 text-xs ${validSearch?"bg-cyan-400/10 text-cyan-100":"bg-rose-400/10 text-rose-100"}`}>{t("Each training window will execute")} <strong>{combinations}</strong> {t("backtests")}。{t("Maximum 500 backtests per run.")}</div><Field label="Ranking metric"><select className="input" value={ranking} onChange={e=>setRanking(e.target.value as OptimizationMetric)}>{metricOptions.map(([key,label])=><option value={key} key={key}>{t(label)}</option>)}</select></Field>{mode==="rolling_6m"&&<NumberField label="Fixed MA comparison" value={fixedMA} onChange={setFixedMA}/>}</Section>
        <FixedParameters form={form} setTop={top} setParam={param}/>
        {mode==="single"?<Section title="Out-of-sample validation"><label className="flex min-h-11 items-center gap-2 text-sm"><input type="checkbox" checked={trainTest.enabled} onChange={e=>setTrainTest({...trainTest,enabled:e.target.checked})}/>{t("Out-of-sample validation")} <span className="text-xs text-slate-500">({t("Optional; disabled by default")})</span></label>{trainTest.enabled&&<><div className="mt-2 grid grid-cols-2 gap-2"><Field label="Training start"><input className="input" type="date" value={trainTest.train_start} onChange={e=>setTrainTest({...trainTest,train_start:e.target.value})}/></Field><Field label="Training end"><input className="input" type="date" value={trainTest.train_end} onChange={e=>setTrainTest({...trainTest,train_end:e.target.value})}/></Field><Field label="Test start"><input className="input" type="date" value={trainTest.test_start} onChange={e=>setTrainTest({...trainTest,test_start:e.target.value})}/></Field><Field label="Test end"><input className="input" type="date" value={trainTest.test_end} onChange={e=>setTrainTest({...trainTest,test_end:e.target.value})}/></Field></div><p className="mb-0 text-[11px] text-slate-500">{t("Test data is never used to select the best MA period.")}</p></>}</Section>:<section className="rounded-lg border border-amber-400/20 bg-amber-400/10 p-3 text-xs leading-5 text-amber-100"><strong>{t("Independent test segments")}</strong><br/>{t("Each 6-month test segment starts flat. Segment-chained return is not continuous portfolio execution and positions do not carry across boundaries.")}</section>}
        <button disabled={!validSearch||starting||active(selected)} className="flex min-h-12 items-center justify-center gap-2 rounded-lg bg-emerald-400 font-extrabold text-slate-950 disabled:opacity-50"><Play size={17} fill="currentColor"/>{t(active(selected)?"Running MA optimization":"Run optimization")}</button>
        <p className="m-0 text-[11px] leading-5 text-slate-500">{t("The optimizer changes only MA period and calls the canonical backtest engine for every row.")}</p>
      </section>
      <section className="min-w-0 space-y-4">
        {selected?<>
          <JobProgress job={selected} progress={progress} onRefresh={async()=>setSelected(await api.optimization(selected.id))} onCancel={async()=>setSelected(await api.cancelOptimization(selected.id))} onRetry={async()=>{const next=await api.retryOptimization(selected.id);setSelected(next);await loadHistory();}}/>
          {selected.result.mode==="rolling_6m"?<RollingResults job={selected}/>:<>{best&&<section className="panel p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="m-0 text-[10px] uppercase tracking-widest text-emerald-300">{t("Best result")}</p><h2 className="mb-0 mt-1 text-2xl font-semibold">MA {best.ma_period}</h2><p className="m-0 text-xs text-slate-500">{t("Ranked by")}：{metricLabel(sortMetric)}</p></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Kpi label="Total return" value={pct(best.total_return)}/><Kpi label="CAGR" value={pct(best.cagr)}/><Kpi label="Maximum drawdown" value={pct(best.max_drawdown)}/><Kpi label="Sharpe" value={ratio(best.sharpe_ratio)}/></div></div><p className="mb-0 mt-3 text-[11px] text-amber-200">{t("Best does not mean future-optimal or production-validated.")}</p></section>}
          {selected.result.train_test?.enabled&&selected.result.train_test.test_result&&<TrainTest result={selected.result.train_test}/>} 
          {rows.length>0&&<>
            <section className="grid gap-4 lg:grid-cols-2"><ChartPanel title="MA performance chart"><select className="input mb-3 max-w-52" value={chartMetric} onChange={e=>setChartMetric(e.target.value as OptimizationMetric)}>{metricOptions.filter(([key])=>key!=="net_pnl").map(([key,label])=><option key={key} value={key}>{t(label)}</option>)}</select><ResponsiveContainer width="100%" height={280}><LineChart data={performanceData}><CartesianGrid stroke="#223247"/><XAxis dataKey="ma" stroke="#8091a7"/><YAxis stroke="#8091a7" width={55}/><Tooltip contentStyle={{background:"#0e1622",border:"1px solid #304159"}}/><Line type="monotone" dataKey="value" stroke="#34d399" dot={false}/></LineChart></ResponsiveContainer></ChartPanel><ChartPanel title="Nearby parameter performance"><div className={`mb-3 rounded p-2 text-xs ${stability?"bg-emerald-400/10 text-emerald-200":"bg-amber-400/10 text-amber-100"}`}>{t(stability?"Nearby parameters are relatively stable":"Stability around this optimum is low")}</div><div className="scrollbar max-h-[300px] overflow-auto"><table className="table"><thead><tr><th>{t("MA period")}</th><th>{metricLabel(sortMetric)}</th></tr></thead><tbody>{nearby.map(row=><tr key={row.ma_period}><td>MA {row.ma_period}</td><td>{metricValue(row,sortMetric)}</td></tr>)}</tbody></table></div></ChartPanel></section>
            <ChartPanel title="Equity curve comparison"><p className="mt-0 text-xs text-slate-500">{t("Select up to five MA periods")}</p>{equityData.length?<ResponsiveContainer width="100%" height={320}><LineChart data={equityData}><CartesianGrid stroke="#223247"/><XAxis dataKey="date" minTickGap={40} stroke="#8091a7"/><YAxis stroke="#8091a7" width={70}/><Tooltip contentStyle={{background:"#0e1622",border:"1px solid #304159"}}/><Legend/>{curves.map((ma,index)=><Line key={ma} dataKey={`MA${ma}`} stroke={["#22d3ee","#34d399","#fbbf24","#fb7185","#a78bfa"][index]} dot={false} connectNulls={false}/>)}</LineChart></ResponsiveContainer>:<div className="grid h-40 place-items-center text-sm text-slate-500">{t("No curve selected")}</div>}</ChartPanel>
            <ResultsTable rows={sorted} sortMetric={sortMetric} setSortMetric={setSortMetric} curves={curves} toggleCurve={toggleCurve}/>
          </>}</>}
        </>:<Empty/>}
        <HistoryPanel jobs={jobs} onOpen={job=>{setSelected(job);setSortMetric(job.result.ranking_metric??job.payload.ranking_metric);setChartMetric(job.result.ranking_metric??job.payload.ranking_metric);setCurves([]);}}/>
      </section>
    </form>
  </main>;
}

function Section({title,open=false,children}:{title:string;open?:boolean;children:React.ReactNode}){return <details open={open} className="settings-section"><summary><strong>{t(title)}</strong></summary><div className="border-t border-[#223247] p-3">{children}</div></details>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field min-w-0"><span>{t(label)}</span>{children}</label>}
function NumberField({label,value,onChange,decimal=false}:{label:string;value:number;onChange:(v:number)=>void;decimal?:boolean}){return <Field label={label}><input className="input" type="number" inputMode={decimal?"decimal":"numeric"} step={decimal?"0.1":"1"} value={value} onChange={e=>onChange(Number(e.target.value))}/></Field>}

function FixedParameters({form,setTop,setParam}:{form:FormState;setTop:<K extends keyof FormState>(k:K,v:FormState[K])=>void;setParam:<K extends keyof Parameters>(k:K,v:Parameters[K])=>void}){
  const advanced=form.strategy!=="simple";
  return <Section title="Fixed strategy parameters"><div className="grid grid-cols-2 gap-2"><Field label="MA type"><select className="input" value={form.parameters.ma_type} onChange={e=>setParam("ma_type",e.target.value as Parameters["ma_type"])}><option value="sma">SMA</option><option value="ema">EMA</option></select></Field><NumberField label="Breakout trigger %" value={form.parameters.breakout_trigger_pct} decimal onChange={v=>setParam("breakout_trigger_pct",v)}/><NumberField label="Entry stop %" value={form.parameters.entry_stop_pct} decimal onChange={v=>setParam("entry_stop_pct",v)}/>{!advanced&&<NumberField label="Exit below MA %" value={form.parameters.exit_below_ma_pct} decimal onChange={v=>setParam("exit_below_ma_pct",v)}/>} {advanced&&<><NumberField label="Volume increase %" value={form.parameters.volume_increase_pct} decimal onChange={v=>setParam("volume_increase_pct",v)}/><NumberField label="MA risk threshold %" value={form.parameters.ma_risk_pct} decimal onChange={v=>setParam("ma_risk_pct",v)}/>{form.strategy==="advanced_day1_stop"&&<NumberField label="Day 1 Stop Below MA %" value={form.parameters.day1_stop_pct} decimal onChange={v=>setParam("day1_stop_pct",v)}/>}<NumberField label="First take profit %" value={form.parameters.first_tp_pct} decimal onChange={v=>setParam("first_tp_pct",v)}/><NumberField label="Bias lookback" value={form.parameters.bias_lookback} onChange={v=>setParam("bias_lookback",v)}/><NumberField label="Bias sigma multiple" value={form.parameters.bias_sigma_multiple} decimal onChange={v=>setParam("bias_sigma_multiple",v)}/><NumberField label="ATR period" value={form.parameters.atr_period} onChange={v=>setParam("atr_period",v)}/><NumberField label="ATR multiple" value={form.parameters.atr_multiple} decimal onChange={v=>setParam("atr_multiple",v)}/><NumberField label="Extreme TP % Q0" value={form.parameters.extreme_tp_pct_q0} decimal onChange={v=>setParam("extreme_tp_pct_q0",v)}/><NumberField label="Maximum TP count" value={form.parameters.max_extreme_tp_count} onChange={v=>setParam("max_extreme_tp_count",v)}/><NumberField label="Minimum position % Q0" value={form.parameters.minimum_position_pct_q0} decimal onChange={v=>setParam("minimum_position_pct_q0",v)}/></>}<NumberField label="Initial capital" value={form.initial_capital} decimal onChange={v=>setTop("initial_capital",v)}/><NumberField label="Position size %" value={form.position_size_pct} decimal onChange={v=>setTop("position_size_pct",v)}/><NumberField label="Commission %" value={form.commission_pct} decimal onChange={v=>setTop("commission_pct",v)}/><NumberField label="Slippage %" value={form.slippage_pct} decimal onChange={v=>setTop("slippage_pct",v)}/></div><label className="mt-3 flex items-center gap-2 text-xs"><input type="checkbox" checked={form.force_close_at_end} onChange={e=>setTop("force_close_at_end",e.target.checked)}/>{t("Force close at end")}</label></Section>
}

function JobProgress({job,progress,onRefresh,onCancel,onRetry}:{job:OptimizationJob;progress:number;onRefresh:()=>void;onCancel:()=>void;onRetry:()=>void}){const skipped=job.result.skipped?.length??0;const canRetry=["FAILED","FAILED_VALIDATION","PARTIAL_SUCCESS"].includes(job.status);const rolling=job.payload.mode==="rolling_6m"||job.result.mode==="rolling_6m";const detail=job.result.rolling_progress;return <section className="panel p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><h2 className="m-0 text-sm font-semibold">{t(rolling?"Running rolling 6-month optimization":"Running MA optimization")}</h2><p className="mb-0 mt-1 text-xs text-slate-500">{job.progress_current} / {job.progress_total} · {t("Current")}：{job.current_item??"—"} · {t("Skipped / insufficient history")}：{skipped} · {t("Failed")}：{job.errors.length}</p>{rolling&&detail&&<p className="mb-0 mt-1 text-xs text-cyan-200">{t("Window")} {detail.window} / {detail.windows_total} · {t(detail.phase)}{detail.ma_total?` · MA ${detail.ma_current??0} / ${detail.ma_total}`:""}</p>}</div><span className="rounded bg-slate-800 px-2 py-1 text-[10px]">{t(job.status)}</span></div><div className="mt-3 h-2 overflow-hidden rounded bg-slate-800"><div className="h-full bg-emerald-400 transition-all" style={{width:`${progress}%`}}/></div><p className="mb-0 mt-2 text-xs text-slate-400">{job.message}</p>{job.payload.train_test?.enabled&&job.payload.mode!=="rolling_6m"&&<p className="mt-2 rounded bg-cyan-400/10 p-2 text-xs text-cyan-100">{t("The saved job includes Train/Test validation.")} {job.payload.train_test.train_start} → {job.payload.train_test.test_end}</p>}{rolling&&<p className="mt-2 rounded bg-cyan-400/10 p-2 text-xs text-cyan-100">{t("Only each prior 6-month training segment selects the MA used in the following 6-month test segment.")}</p>}{job.errors.length>0&&<div className="mt-3 grid gap-2">{job.errors.map((item,index)=><div key={`${item.code}-${index}`} className="rounded border border-rose-400/25 bg-rose-400/10 p-3 text-xs"><strong className="text-rose-100">{t("Failure reason")}：{errorText(item.message??"",item.code)}</strong><p className="mb-0 mt-1 text-rose-200/80">{t("Failure stage")}：{t(item.stage??job.result.failure_stage??"—")}</p><details className="mt-2"><summary className="cursor-pointer text-slate-400">{t("Technical details")}</summary><pre className="technical-raw mt-2 whitespace-pre-wrap text-[10px] text-slate-500">{JSON.stringify(item,null,2)}</pre></details></div>)}</div>}<div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={onRefresh} className="flex min-h-10 items-center gap-2 rounded border border-[#304159] px-3 text-xs"><RefreshCw size={14}/>{t("Refresh")}</button>{active(job)&&<button type="button" onClick={onCancel} className="flex min-h-10 items-center gap-2 rounded border border-rose-400/30 px-3 text-xs text-rose-200"><Square size={12}/>{t("Cancel optimization")}</button>}{canRetry&&<button type="button" onClick={onRetry} className="flex min-h-10 items-center gap-2 rounded border border-amber-400/30 px-3 text-xs text-amber-100"><RefreshCw size={14}/>{t("Retry optimization")}</button>}</div></section>}
function Kpi({label,value}:{label:string;value:string}){return <div className="min-w-24"><p className="m-0 text-[9px] uppercase text-slate-500">{t(label)}</p><p className="m-0 text-lg font-semibold">{value}</p></div>}
function ChartPanel({title,children}:{title:string;children:React.ReactNode}){return <section className="panel min-w-0 overflow-hidden"><h3 className="m-0 border-b border-[#223247] px-4 py-3 text-sm">{t(title)}</h3><div className="p-3">{children}</div></section>}
function TrainTest({result}:{result:NonNullable<OptimizationJob["result"]["train_test"]>}){const a=result.train_best!,b=result.test_result!;return <section className="panel p-4"><h3 className="m-0 text-sm">{t("Out-of-sample validation")}</h3><p className="text-[11px] text-slate-500">{t("Test data is never used to select the best MA period.")}</p><div className="grid grid-cols-2 gap-3"><div className="rounded bg-[#0a111b] p-3"><strong className="text-xs">{t("Train best")}：MA {a.ma_period}</strong><p className="mb-0 text-sm">Sharpe {ratio(a.sharpe_ratio)} · {pct(a.total_return)}</p></div><div className="rounded bg-[#0a111b] p-3"><strong className="text-xs">{t("Test performance")}：MA {b.ma_period}</strong><p className="mb-0 text-sm">Sharpe {ratio(b.sharpe_ratio)} · {pct(b.total_return)}</p></div></div></section>}

function RollingResults({job}:{job:OptimizationJob}){
  const result=job.result,aggregate=result.test_only_aggregate,fixed=result.fixed_ma_aggregate,summary=result.selection_summary,relationship=result.train_test_relationship;
  const windows=result.rolling_windows??[],history=result.selection_history??[];
  if(!windows.length&&!aggregate)return null;
  return <>
     {result.selection_mode==="STRUCTURE_V1"&&<><StructureRollingPanel job={job} windows={windows}/><StructureComparison job={job} windows={windows}/><StructureWindowDetails windows={windows}/></>} 
    {aggregate&&<section className="panel p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="m-0 text-[10px] uppercase tracking-widest text-emerald-300">{t("Rolling optimization summary")}</p><h2 className="mb-0 mt-1 text-lg">{t("Test-only aggregate")}</h2></div><span className="rounded bg-emerald-400/10 px-2 py-1 text-[10px] text-emerald-200">{aggregate.complete_test_windows} {t("complete test windows")}</span></div><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4"><Kpi label="Positive test windows" value={`${aggregate.positive_return_windows} / ${aggregate.complete_test_windows}`}/><Kpi label="Average test return" value={pct(aggregate.average_6m_return)}/><Kpi label="Median test return" value={pct(aggregate.median_6m_return)}/><Kpi label="Average test Sharpe" value={ratio(aggregate.average_sharpe)}/><Kpi label="Worst 6-month return" value={pct(aggregate.worst_6m_return)}/><Kpi label="Best 6-month return" value={pct(aggregate.best_6m_return)}/><Kpi label="Selected MA median" value={summary?.median_ma==null?"—":num(summary.median_ma,1)}/><Kpi label="Selected MA range" value={summary?.minimum_ma==null?"—":`${summary.minimum_ma}～${summary.maximum_ma}`}/><Kpi label="Fixed MA chained return" value={pct(fixed?.segment_chained_return)}/><Kpi label="Rolling minus fixed MA" value={aggregate.segment_chained_return!=null&&fixed?.segment_chained_return!=null?pct(aggregate.segment_chained_return-fixed.segment_chained_return):"—"}/></div><div className="mt-4 rounded border border-amber-400/20 bg-amber-400/10 p-3 text-xs leading-5 text-amber-100"><strong>{t("6-month segment-chained OOS return")}：{pct(aggregate.segment_chained_return)}</strong><br/>{t("This geometrically chains independent test segment returns. It is not continuous portfolio equity and carries no position across a six-month boundary.")}</div></section>}
    {history.length>0&&<section className="grid gap-4 lg:grid-cols-2"><ChartPanel title="Selected MA history"><ResponsiveContainer width="100%" height={280}><LineChart data={history.map(item=>({period:item.test_start.slice(0,7),ma:item.selected_ma,formal:item.aggregate_included}))}><CartesianGrid stroke="#223247"/><XAxis dataKey="period" minTickGap={24} stroke="#8091a7"/><YAxis stroke="#8091a7" width={45}/><Tooltip contentStyle={{background:"#0e1622",border:"1px solid #304159"}}/><Line type="stepAfter" dataKey="ma" name={t("Selected MA")} stroke="#22d3ee" dot/></LineChart></ResponsiveContainer></ChartPanel><ChartPanel title="Train to test relationship"><div className="grid grid-cols-2 gap-3"><Kpi label="Train/Test metric correlation" value={ratio(relationship?.train_test_metric_correlation)}/><Kpi label="Train/Test return correlation" value={ratio(relationship?.train_test_return_correlation)}/><Kpi label="Positive test return ratio" value={pct(relationship?.test_positive_return_ratio)}/><Kpi label="Test Sharpe above zero" value={pct(relationship?.test_positive_sharpe_ratio)}/><Kpi label="Test Sharpe above 1.0" value={pct(relationship?.test_sharpe_above_display_threshold_ratio)}/><Kpi label="MA standard deviation" value={ratio(summary?.ma_standard_deviation)}/><Kpi label="Average adjacent MA change" value={ratio(summary?.average_adjacent_change)}/></div><p className="mb-0 mt-3 text-[11px] text-slate-500">{t("These are descriptive statistics only and never alter MA selection.")}</p></ChartPanel></section>}
    <RollingTable windows={windows} ranking={result.ranking_metric??job.payload.ranking_metric}/>
  </>;
}

function StructureRollingPanel({job,windows}:{job:OptimizationJob;windows:RollingOptimizationWindow[]}){
  const [windowIndex,setWindowIndex]=useState(windows[0]?.index??1);
  const current=windows.find(item=>item.index===windowIndex)??windows[0];
  const candidates=current?.structure_top5??[];
  const [maPeriod,setMaPeriod]=useState<number>(candidates[0]?.ma_period??current?.selected_ma??0);
  const [artifact,setArtifact]=useState<StructureArtifact|null>(null);
  useEffect(()=>{setMaPeriod(candidates[0]?.ma_period??current?.selected_ma??0);},[windowIndex,current?.selected_ma]);
  useEffect(()=>{if(!current||!maPeriod)return;let cancelled=false;api.structureArtifact(job.id,current.index,maPeriod).then(value=>{if(!cancelled)setArtifact(value.artifact);}).catch(()=>{if(!cancelled)setArtifact(null);});return()=>{cancelled=true;};},[job.id,current?.index,maPeriod]);
  // The metric cards follow the Top-5 selector.  The selected Structure MA is
  // only the default, so inspecting another saved candidate never displays
  // the wrong raw/percentile/count values.
  const selected=candidates.find(item=>item.ma_period===maPeriod)??current?.structure_best;
  const performanceAggregate=job.result.performance_aggregate;
  const structureAggregate=job.result.structure_aggregate??job.result.test_only_aggregate;
  const componentCards=[
    {label:"多空分界能力",rawLabel:"原始值",raw:selected?.regime_raw??null,component:selected?.structure_ranking?.ranking_values.regime??null,percentile:selected?.regime_percentile??null,wilson:null},
    {label:"均線回測能力",rawLabel:"原始成功率",raw:selected?.retest_raw??null,component:selected?.structure_ranking?.ranking_values.retest??null,percentile:selected?.retest_percentile??null,wilson:selected?.retest_wilson_lower??null},
    {label:"突破後 +3%",rawLabel:"原始成功率",raw:selected?.breakout_raw??null,component:selected?.structure_ranking?.ranking_values.breakout??null,percentile:selected?.breakout_percentile??null,wilson:selected?.breakout_wilson_lower??null},
    {label:"第二日確認一致性",rawLabel:"原始一致性",raw:selected?.confirmation_raw??null,component:selected?.structure_ranking?.ranking_values.confirmation??null,percentile:selected?.confirmation_percentile??null,wilson:null},
  ];
  const structureRevision=job.result.structure_implementation_revision;
  const legacyStructureResult=!structureRevision||structureRevision!=="MA_STRUCTURE_V1_IMPL_2";
  return <section className="panel p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="m-0 text-[10px] uppercase tracking-widest text-cyan-300">{t("K 線結構分數")}</p><h2 className="mb-0 mt-1 text-lg">{t("依 K 線結構")}</h2><p className="m-0 mt-1 text-[11px] text-slate-500">{t("Retrospective OOS comparison; does not establish future predictive ability.")}</p><p className="m-0 mt-1 text-[10px] text-slate-500">{t("Frozen Structure specification")}：{job.result.structure_spec_version??"MA_STRUCTURE_V1"} · {job.result.structure_spec_hash?.slice(0,12)??"—"}… · Impl {structureRevision??"PRIOR_INVALIDATED_IMPLEMENTATION"}</p>{legacyStructureResult&&<p className="m-0 mt-2 rounded border border-amber-400/30 bg-amber-400/10 p-2 text-[11px] text-amber-100">{t("PRIOR_INVALIDATED_IMPLEMENTATION")}</p>}</div><div className="flex flex-wrap gap-2"><Field label="Train/Test window"><select className="input" value={current?.index??1} onChange={e=>setWindowIndex(Number(e.target.value))}>{windows.map(item=><option key={item.index} value={item.index}>{item.train_start} ～ {item.test_end}</option>)}</select></Field><Field label="Top Structure MA"><select className="input" value={maPeriod} onChange={e=>setMaPeriod(Number(e.target.value))}>{candidates.map(item=><option key={item.ma_period} value={item.ma_period}>MA {item.ma_period}</option>)}</select></Field></div></div><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4"><Kpi label="Top MA" value={selected?.ma_period?`MA ${selected.ma_period}`:"—"}/><Kpi label="K 線結構分數" value={selected?.ma_structure_score==null?"—":selected.ma_structure_score.toFixed(3)}/><Kpi label="多空分界能力" value={selected?.regime_percentile==null?"—":selected.regime_percentile.toFixed(3)}/><Kpi label="均線回測能力" value={selected?.retest_percentile==null?"—":selected.retest_percentile.toFixed(3)}/><Kpi label="突破後 +3%" value={selected?.breakout_percentile==null?"—":selected.breakout_percentile.toFixed(3)}/><Kpi label="第二日確認一致性" value={selected?.confirmation_percentile==null?"—":selected.confirmation_percentile.toFixed(3)}/><Kpi label="成功突破" value={`${selected?.breakout_success_count??0} / ${selected?.breakout_resolved_count??0}`}/><Kpi label="突破 Wilson 下界" value={selected?.breakout_wilson_lower==null?"—":selected.breakout_wilson_lower.toFixed(3)}/></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4">{componentCards.map(card=><div key={card.label} className="rounded border border-[#27384d] bg-[#0a111b] p-3"><p className="m-0 text-[10px] text-slate-400">{card.label}</p><p className="m-0 mt-1 text-sm font-semibold">{card.raw==null?`${card.rawLabel} —`:`${card.rawLabel} ${card.raw.toFixed(4)}`}</p>{card.wilson!=null&&<p className="m-0 text-xs text-violet-200">Wilson 下界 {card.wilson.toFixed(4)}</p>}<p className="m-0 text-xs text-cyan-200">排序值 {card.component==null?"—":card.component.toFixed(4)}</p><p className="m-0 text-xs text-emerald-200">百分位 {card.percentile==null?"—":card.percentile.toFixed(4)}</p></div>)}</div><div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4"><Kpi label="Retest Wilson" value={selected?.retest_wilson_lower==null?"—":selected.retest_wilson_lower.toFixed(3)}/><Kpi label="Breakout Wilson" value={selected?.breakout_wilson_lower==null?"—":selected.breakout_wilson_lower.toFixed(3)}/><Kpi label="Retest events" value={`${selected?.retest_success_count??0} / ${selected?.retest_resolved_count??0}`}/><Kpi label="Confirmation resolved" value={`${selected?.confirmation_resolved_count??0}`}/><Kpi label="Confirmation violation rate" value={selected?.confirmation_violation_rate==null?"—":pct(selected.confirmation_violation_rate)}/><Kpi label="Bull / bear breakouts" value={`${selected?.bull_breakout_count??0} / ${selected?.bear_breakout_count??0}`}/><Kpi label="Gap / missed" value={`${selected?.gap_breakout_count??0} / ${selected?.entry_zone_missed_count??0}`}/><Kpi label="Execution feasibility" value={selected?.execution_feasibility_ratio==null?"—":pct(selected.execution_feasibility_ratio)}/></div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4"><Kpi label="Performance OOS aggregate" value={pct(performanceAggregate?.segment_chained_return)}/><Kpi label="Structure OOS aggregate" value={pct(structureAggregate?.segment_chained_return)}/><Kpi label="Structure − Performance" value={performanceAggregate?.segment_chained_return!=null&&structureAggregate?.segment_chained_return!=null?pct(structureAggregate.segment_chained_return-performanceAggregate.segment_chained_return):"—"}/><Kpi label="Fixed MA OOS aggregate" value={pct(job.result.fixed_ma_aggregate?.segment_chained_return)}/></div><div className="mt-4 scrollbar overflow-auto"><table className="table"><thead><tr><th>{t("Window")}</th><th>{t("Performance Test return")}</th><th>{t("Structure Test return")}</th><th>{t("Structure − Performance return")}</th></tr></thead><tbody>{windows.map(item=><tr key={item.index}><td>{item.index}</td><td>{pct(item.performance_test_result?.total_return)}</td><td>{pct(item.structure_test_result?.total_return)}</td><td>{pct(item.structure_minus_performance?.return_delta)}</td></tr>)}</tbody></table></div>{candidates.length>0&&<div className="mt-4 scrollbar overflow-auto"><table className="table"><thead><tr><th>{t("MA period")}</th><th>{t("K 線結構分數")}</th><th>{t("多空分界能力")}</th><th>{t("均線回測能力")}</th><th>{t("突破後 +3%")}</th><th>{t("第二日確認一致性")}</th><th>{t("Train performance reference only")}</th></tr></thead><tbody>{candidates.map(item=><tr key={item.ma_period}><td>MA {item.ma_period}</td><td>{item.ma_structure_score==null?"—":item.ma_structure_score.toFixed(3)}</td><td>{item.regime_percentile==null?"—":item.regime_percentile.toFixed(3)}</td><td>{item.retest_percentile==null?"—":item.retest_percentile.toFixed(3)}</td><td>{item.breakout_percentile==null?"—":item.breakout_percentile.toFixed(3)}</td><td>{item.confirmation_percentile==null?"—":item.confirmation_percentile.toFixed(3)}</td><td>{item.train_sharpe==null?"—":ratio(item.train_sharpe)} / {item.train_return==null?"—":pct(item.train_return)}</td></tr>)}</tbody></table></div>}<div className="mt-4"><StructureChart artifact={artifact}/></div><p className="m-0 mt-3 text-[11px] text-amber-200">{t("Train performance is reference only and does not participate in Structure selection.")} · {t("Tie-break reason")}：{t(current?.structure_tie_break_reason??"—")}</p></section>;
}

function StructureComparison({job,windows}:{job:OptimizationJob;windows:RollingOptimizationWindow[]}){
  const performance=job.result.performance_aggregate;
  const structure=job.result.structure_aggregate??job.result.test_only_aggregate;
  return <section className="panel overflow-hidden"><div className="border-b border-[#223247] p-4"><h3 className="m-0 text-sm">{t("Performance vs Structure comparison")}</h3><p className="m-0 mt-1 text-[11px] text-slate-500">{t("Structure is selected from Train OHLC only; all Test rows use the canonical engine from flat.")}</p></div><div className="optimization-desktop scrollbar overflow-auto"><table className="table"><thead><tr><th>{t("Window")}</th><th>{t("Performance-selected MA")}</th><th>{t("Structure-selected MA")}</th><th>{t("Performance Test return")}</th><th>{t("Structure Test return")}</th><th>{t("Structure − Performance return")}</th><th>{t("Structure − Performance Sharpe")}</th></tr></thead><tbody>{windows.map(item=><tr key={item.index}><td>{item.index}<br/><span className="text-[10px] text-slate-500">{item.test_start}～{item.test_end}</span></td><td>MA {item.performance_best?.ma_period??"—"}</td><td>MA {item.structure_best?.ma_period??"—"}</td><td>{pct(item.performance_test_result?.total_return)}</td><td>{pct(item.structure_test_result?.total_return)}</td><td>{pct(item.structure_minus_performance?.return_delta)}</td><td>{ratio(item.structure_minus_performance?.sharpe_delta)}</td></tr>)}</tbody></table></div><div className="optimization-mobile grid gap-2 p-3">{windows.map(item=><article key={item.index} className="rounded-lg border border-[#27384d] bg-[#0a111b] p-3"><strong className="text-xs">{t("Window")} {item.index} · {item.test_start}～{item.test_end}</strong><div className="mt-2 grid grid-cols-2 gap-2"><Kpi label="Performance-selected MA" value={item.performance_best?.ma_period?`MA ${item.performance_best.ma_period}`:"—"}/><Kpi label="Structure-selected MA" value={item.structure_best?.ma_period?`MA ${item.structure_best.ma_period}`:"—"}/><Kpi label="Performance Test return" value={pct(item.performance_test_result?.total_return)}/><Kpi label="Structure Test return" value={pct(item.structure_test_result?.total_return)}/><Kpi label="Structure − Performance return" value={pct(item.structure_minus_performance?.return_delta)}/><Kpi label="Structure − Performance Sharpe" value={ratio(item.structure_minus_performance?.sharpe_delta)}/></div></article>)}</div><div className="grid grid-cols-2 gap-3 border-t border-[#223247] p-4 sm:grid-cols-4"><Kpi label="Performance OOS aggregate" value={pct(performance?.segment_chained_return)}/><Kpi label="Structure OOS aggregate" value={pct(structure?.segment_chained_return)}/><Kpi label="Structure − Performance" value={performance?.segment_chained_return!=null&&structure?.segment_chained_return!=null?pct(structure.segment_chained_return-performance.segment_chained_return):"—"}/><Kpi label="Fixed MA OOS aggregate" value={pct(job.result.fixed_ma_aggregate?.segment_chained_return)}/></div></section>;
}

function StructureWindowDetails({windows}:{windows:RollingOptimizationWindow[]}){
  return <section className="panel p-4"><h3 className="m-0 text-sm">{t("Structure candidate details")}</h3><p className="m-0 mt-1 text-[11px] text-slate-500">{t("Train performance is reference only and does not participate in Structure selection.")}</p><div className="mt-3 grid gap-2">{windows.map(item=>{const candidate=item.structure_best; if(!candidate)return null; return <details key={item.index} className="rounded border border-[#27384d] bg-[#0a111b] p-3"><summary className="cursor-pointer text-xs text-cyan-200">{t("Window")} {item.index} · MA {candidate.ma_period} · {t("K 線結構分數")} {num(candidate.ma_structure_score,3)}</summary><div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4"><Kpi label="Bull regime" value={`${candidate.bull_success_count??0} / ${candidate.bull_regime_count??0}`}/><Kpi label="Bear regime" value={`${candidate.bear_success_count??0} / ${candidate.bear_regime_count??0}`}/><Kpi label="Bull retest" value={`${candidate.bull_retest_success_count??0} / ${candidate.bull_retest_count??0}`}/><Kpi label="Bear retest" value={`${candidate.bear_retest_success_count??0} / ${candidate.bear_retest_count??0}`}/><Kpi label="Bull breakout" value={`${candidate.bull_breakout_success_count??0} / ${candidate.bull_breakout_fail_count??0} / ${candidate.bull_breakout_unresolved_count??0}`}/><Kpi label="Bear breakout" value={`${candidate.bear_breakout_success_count??0} / ${candidate.bear_breakout_fail_count??0} / ${candidate.bear_breakout_unresolved_count??0}`}/><Kpi label="Bull Wilson" value={num(candidate.bull_breakout_wilson_lower,3)}/><Kpi label="Bear Wilson" value={num(candidate.bear_breakout_wilson_lower,3)}/><Kpi label="Train Return" value={pct(candidate.train_return)}/><Kpi label="Train Sharpe" value={ratio(candidate.train_sharpe)}/></div></details>})}</div></section>;
}

function RollingTable({windows,ranking}:{windows:RollingOptimizationWindow[];ranking:OptimizationMetric}){return <section className="panel overflow-hidden"><div className="border-b border-[#223247] p-4"><h3 className="m-0 text-sm">{t("6-month rolling results")}</h3><p className="mb-0 mt-1 text-[11px] text-slate-500">{t("Each test segment is an independent canonical backtest that starts flat.")}</p></div><div className="optimization-desktop scrollbar overflow-auto"><table className="table"><thead><tr><th>{t("Train period")}</th><th>{t("Test period")}</th><th>{t("Selected MA")}</th><th>{t("Train metric")}</th><th>{t("Train Sharpe")}</th><th>{t("Train return")}</th><th>{t("Test Sharpe")}</th><th>{t("Test return")}</th><th>{t("Test MDD")}</th><th>{t("Test Net PnL")}</th><th>{t("Trades")}</th><th>{t("Final equity")}</th><th>{t("Fixed MA return")}</th><th>{t("Status")}</th><th>{t("Actions")}</th></tr></thead><tbody>{windows.map(item=><RollingRow key={item.index} item={item} ranking={ranking}/>)}</tbody></table></div><div className="optimization-mobile grid gap-2 p-3">{windows.map(item=><RollingCard key={item.index} item={item} ranking={ranking}/>)}</div></section>}

function RollingRow({item,ranking}:{item:RollingOptimizationWindow;ranking:OptimizationMetric}){const train=item.train_best,test=item.test_result,fixed=item.fixed_test_result;return <><tr className={!item.aggregate_included?"text-slate-400":""}><td>{item.train_start}<br/>{item.train_end}</td><td>{item.test_start}<br/>{item.test_end}</td><td className="font-semibold">{item.selected_ma?`MA ${item.selected_ma}`:"—"}</td><td>{train?metricValue(train,ranking):"—"}</td><td>{ratio(train?.sharpe_ratio)}</td><td>{pct(train?.total_return)}</td><td>{ratio(test?.sharpe_ratio)}</td><td>{pct(test?.total_return)}</td><td>{pct(test?.max_drawdown)}</td><td>{test?money(test.net_pnl):"—"}</td><td>{test?.number_of_positions??"—"}</td><td>{test?money(test.final_equity):"—"}</td><td>{fixed?`MA ${item.fixed_ma_period} · ${pct(fixed.total_return)}`:"—"}</td><td>{t(item.status)}</td><td>{test?<Link href={`/?backtest_id=${encodeURIComponent(test.backtest_id)}`} className="text-cyan-300">{t("View complete test backtest")}</Link>:"—"}</td></tr><tr><td colSpan={15} className="!p-0"><RankingDetails item={item} ranking={ranking}/></td></tr></>}

function RollingCard({item,ranking}:{item:RollingOptimizationWindow;ranking:OptimizationMetric}){const test=item.test_result;return <article className="rounded-lg border border-[#27384d] bg-[#0a111b] p-3"><div className="flex items-start justify-between gap-2"><div><strong className="text-sm">{t("Test")} {item.test_start}～{item.test_end}</strong><p className="mb-0 mt-1 text-[11px] text-slate-500">{t("Train")} {item.train_start}～{item.train_end}</p></div><span className="rounded bg-slate-800 px-2 py-1 text-[9px]">{t(item.status)}</span></div><div className="mt-3 grid grid-cols-2 gap-2"><Kpi label="Selected MA" value={item.selected_ma?`MA ${item.selected_ma}`:"—"}/><Kpi label="Test return" value={pct(test?.total_return)}/><Kpi label="Test Sharpe" value={ratio(test?.sharpe_ratio)}/><Kpi label="Test MDD" value={pct(test?.max_drawdown)}/></div>{test&&<Link href={`/?backtest_id=${encodeURIComponent(test.backtest_id)}`} className="mt-3 block min-h-10 rounded border border-cyan-400/30 p-2 text-center text-xs text-cyan-200">{t("View complete test backtest")}</Link>}<RankingDetails item={item} ranking={ranking}/></article>}

function RankingDetails({item,ranking}:{item:RollingOptimizationWindow;ranking:OptimizationMetric}){return <details className="p-3"><summary className="cursor-pointer text-xs text-cyan-200">{t("Expand train MA ranking")}</summary><div className="mt-2 rounded bg-[#080d14] p-2 text-[11px] text-slate-400"><p className="mt-0">{t("Tie-break reason")}：{t(item.tie_break_reason??"—")} · {t("Actual train sessions")}：{item.train_sessions?.first_session??"—"}～{item.train_sessions?.last_session??"—"}</p>{item.train_stability&&<p className={`rounded p-2 ${item.train_stability.stable?"bg-emerald-400/10 text-emerald-200":"bg-amber-400/10 text-amber-100"}`}>{t(item.train_stability.label)} · MA {item.train_stability.from_ma}～{item.train_stability.to_ma}</p>}<div className="scrollbar max-h-56 overflow-auto"><table className="table"><thead><tr><th>{t("MA period")}</th><th>{metricLabel(ranking)}</th><th>{t("Total return")}</th><th>{t("MDD")}</th></tr></thead><tbody>{(item.train_ranking??[]).map(row=><tr key={row.ma_period}><td>MA {row.ma_period}</td><td>{metricValue(row,ranking)}</td><td>{pct(row.total_return)}</td><td>{pct(row.max_drawdown)}</td></tr>)}</tbody></table></div></div></details>}

function ResultsTable({rows,sortMetric,setSortMetric,curves,toggleCurve}:{rows:OptimizationRow[];sortMetric:OptimizationMetric;setSortMetric:(v:OptimizationMetric)=>void;curves:number[];toggleCurve:(ma:number)=>void}){return <section className="panel overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#223247] p-4"><h3 className="m-0 text-sm">{t("Optimization results")}</h3><Field label="Ranking metric"><select className="input min-w-48" value={sortMetric} onChange={e=>setSortMetric(e.target.value as OptimizationMetric)}>{metricOptions.map(([key,label])=><option key={key} value={key}>{t(label)}</option>)}</select></Field></div><div className="optimization-desktop scrollbar overflow-auto"><table className="table"><thead><tr><th>{t("Chart")}</th><th>{t("MA period")}</th><th>{t("Total return")}</th><th>{t("CAGR")}</th><th>{t("Maximum drawdown")}</th><th>{t("Sharpe")}</th><th>{t("Sortino")}</th><th>{t("Calmar")}</th><th>{t("Number of trades")}</th><th>{t("Win rate")}</th><th>{t("Net PnL")}</th><th>{t("Exposure %")}</th><th>{t("Average holding days")}</th><th>{t("Commission")}</th><th>{t("Slippage cost")}</th><th>{t("Actions")}</th></tr></thead><tbody>{rows.map(row=><tr key={row.ma_period}><td><input aria-label={`MA ${row.ma_period}`} type="checkbox" checked={curves.includes(row.ma_period)} disabled={!curves.includes(row.ma_period)&&curves.length>=5} onChange={()=>toggleCurve(row.ma_period)}/></td><td className="font-semibold">MA {row.ma_period}{row.cache_reused&&<span title={t("Cached result")} className="ml-1 text-emerald-300">●</span>}</td><td>{pct(row.total_return)}</td><td>{pct(row.cagr)}</td><td>{pct(row.max_drawdown)}</td><td>{ratio(row.sharpe_ratio)}</td><td>{ratio(row.sortino_ratio)}</td><td>{ratio(row.calmar_ratio)}</td><td>{row.number_of_positions}</td><td>{pct(row.win_rate)}</td><td>{money(row.net_pnl)}</td><td>{num(row.exposure_pct,1)}%</td><td>{num(row.average_holding_days,1)}</td><td>{money(row.total_commission)}</td><td>{money(row.estimated_slippage_cost)}</td><td><div className="flex gap-2"><Link href={`/?backtest_id=${encodeURIComponent(row.backtest_id)}`} className="text-cyan-300">{t("View full backtest")}</Link><Link href={`/?clone_backtest_id=${encodeURIComponent(row.backtest_id)}`} className="text-emerald-300">{t("Apply this MA")}</Link></div></td></tr>)}</tbody></table></div><div className="optimization-mobile grid gap-2 p-3">{rows.map(row=><article key={row.ma_period} className="rounded-lg border border-[#27384d] bg-[#0a111b] p-3"><div className="flex items-center justify-between"><strong>MA {row.ma_period}</strong><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={curves.includes(row.ma_period)} disabled={!curves.includes(row.ma_period)&&curves.length>=5} onChange={()=>toggleCurve(row.ma_period)}/>{t("Chart")}</label></div><div className="mt-3 grid grid-cols-2 gap-2"><Kpi label="Total return" value={pct(row.total_return)}/><Kpi label="Sharpe" value={ratio(row.sharpe_ratio)}/><Kpi label="Maximum drawdown" value={pct(row.max_drawdown)}/><Kpi label="Net PnL" value={money(row.net_pnl)}/></div><div className="mt-3 grid grid-cols-2 gap-2"><Link href={`/?backtest_id=${encodeURIComponent(row.backtest_id)}`} className="rounded border border-cyan-400/30 p-2 text-center text-xs text-cyan-200">{t("View full backtest")}</Link><Link href={`/?clone_backtest_id=${encodeURIComponent(row.backtest_id)}`} className="rounded border border-emerald-400/30 p-2 text-center text-xs text-emerald-200">{t("Apply this MA")}</Link></div></article>)}</div></section>}
function HistoryPanel({jobs,onOpen}:{jobs:OptimizationJob[];onOpen:(job:OptimizationJob)=>void}){return <section className="panel p-4"><div className="mb-3 flex items-center gap-2"><History size={16} className="text-slate-500"/><h3 className="m-0 text-sm">{t("Optimization history")}</h3></div><div className="grid gap-2">{jobs.length?jobs.map(job=><button type="button" key={job.id} onClick={()=>onOpen(job)} className="flex min-h-12 w-full items-center justify-between gap-3 rounded border border-[#27384d] bg-[#0a111b] p-3 text-left"><span><strong className="block text-xs">{job.payload?.backtest?.ticker??"—"} · {t(job.payload?.backtest?.strategy??"")} · MA {job.payload?.ma_min??"—"}–{job.payload?.ma_max??"—"}</strong><small className="text-slate-500">{t(job.payload.mode==="rolling_6m"?"Re-optimize every 6 months":"Single Train / Test")} · {dateText(job.created_at)} · {t(job.status)}</small></span><span className="text-xs text-cyan-300">{t("Open optimization")}</span></button>):<p className="text-xs text-slate-500">{t("No optimization history yet.")}</p>}</div></section>}
function Empty(){return <section className="panel grid min-h-[460px] place-items-center p-8 text-center"><div><div className="mx-auto grid h-14 w-14 place-items-center rounded-xl border border-emerald-400/25 bg-emerald-400/10 text-emerald-300"><BarChart3/></div><h2 className="mt-4 text-lg">{t("MA period optimization")}</h2><p className="max-w-lg text-sm leading-6 text-slate-400">{t("The optimizer changes only MA period and calls the canonical backtest engine for every row.")}</p><div className="mt-4 flex justify-center gap-2 text-xs text-slate-500"><Activity size={15}/>{t("Maximum 500 backtests per run.")}</div></div></section>}
